contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // We cannot read the private mapping credit directly, so we observe its effects:
    // - When depositing X, address(c).balance increases by X.
    // - If withdrawAll succeeds, address(c).balance decreases by the withdrawn amount and this contract's balance increases by that amount.
    // - If withdrawAll reverts, balances remain as after deposit.
    // From these observable effects we deduce whether the recorded credit was cleared: a successful withdraw transfers exactly the previously deposited amount back, and leaves recorded credit 0; a revert leaves recorded credit unchanged.

    function run(uint depositAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        require(address(this).balance >= depositAmount, "insufficient test balance");

        // Record balances before any interaction
        uint beforeC = address(c).balance;
        uint beforeThis = address(this).balance;

        // Deposit depositAmount into c for this contract
        c.deposit{value: depositAmount}(); if (__ESBMC_reverted()) return;

        // Balances after deposit
        uint afterDepositC = address(c).balance;
        uint afterDepositThis = address(this).balance;

        // Sanity: ensure deposit had intended effect
        require(afterDepositC == beforeC + depositAmount, "deposit didn't increase c balance as expected");
        require(afterDepositThis == beforeThis - depositAmount, "deposit didn't decrease tester balance as expected");

        // Call withdrawAll and capture whether it reverted
        bool reverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // Balances after withdraw attempt
        uint finalC = address(c).balance;
        uint finalThis = address(this).balance;

        // General rule (expressed via observable balances):
        // If withdrawAll reverted, balances must equal the post-deposit balances.
        // If withdrawAll succeeded, then c's balance must have decreased by exactly depositAmount and this contract's balance increased by exactly depositAmount.
        assert( (reverted && finalC == afterDepositC && finalThis == afterDepositThis) ||
                (!reverted && finalC + depositAmount == afterDepositC && finalThis == afterDepositThis + depositAmount) );
    }

    receive() external payable {}
}

